<script lang="ts">
 import {base} from '$app/paths';
 import {present} from '$lib/motion/present'; import {MotionPlayer} from '$lib/motion/player';
 import type {Style,Kind} from '$lib/catalog'; import type {ReviewState,ReviewChoice,Speed} from '$lib/review';
 import{movementArt}from'./card-layout';import PatrolMap from'./PatrolMap.svelte';import DieReview from'./DieReview.svelte';
 import ArtCard from './ArtCard.svelte';import Piece from './Piece.svelte';import Token from './Token.svelte';import Abbey from './Abbey.svelte';
 let {kind,style='moonlit',state:fixture,onchoice,inspectDot=26,oninspect,motion=new MotionPlayer(),audit=false,tabletop=false,onundo,canUndo=false}=$props<{kind:Kind;style?:Style;state:ReviewState;onchoice?:(choice:ReviewChoice)=>void;inspectDot?:number;oninspect?:(dot:number)=>void;motion?:MotionPlayer;audit?:boolean;tabletop?:boolean;onundo?:()=>void;canUndo?:boolean}>();
 let tray=$state<HTMLDivElement>();
 function browse(direction:number){tray?.scrollBy({left:direction*285,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 const speeds:{name:Speed;distance:string;noise:string}[]=[{name:'Still',distance:'0',noise:'−3'},{name:'Sneak',distance:'1–2',noise:'−2'},{name:'Walk',distance:'3–4',noise:'−1'},{name:'Run',distance:'Up to 5',noise:'0'}];
</script>
<div class="shared-component" class:player-components={!audit} data-component={kind} use:present={{signature:JSON.stringify(fixture),player:motion}}>
{#if kind==='board'}<Abbey {style} state={fixture} {onchoice} {inspectDot} {oninspect} {audit} {tabletop} {onundo} {canUndo}/>
{:else if kind==='novices' || kind==='guards'}<div class="character-tray" role="region" aria-label="Character collection">{#each (kind==='guards'?[6,7]:[0,1,2,3,4,5]) as i}<Piece {style} index={i}/>{/each}</div>
{:else if kind==='movement'}<div class="card-review-stack">{#if audit}<div class="tray-controls"><span>Four movement cards · scroll to compare</span><div><button onclick={()=>browse(-1)} aria-label="Previous movement card">←</button><button onclick={()=>browse(1)} aria-label="Next movement card">→</button></div></div>{/if}<div bind:this={tray} class="card-tray" role="region" aria-label={audit?'Four movement cards, scroll to compare':'Choose your movement'}>{#each speeds as speed}<button class="object-button" aria-pressed={fixture.speed===speed.name} onclick={()=>onchoice?.({type:'speed',speed:speed.name})}><ArtCard {style} face="movement" illustration={movementArt[speed.name]} title={speed.name} selected={fixture.speed===speed.name}><div class="movement-values"><strong>{speed.distance}</strong><span>dots</span><b>Noise {speed.noise}</b></div></ArtCard></button>{/each}</div></div>
{:else if kind==='wish'}<button class="object-button card-turn" aria-label={fixture.reversed[kind]?"Reveal secret wish":"Turn secret wish over"} onclick={()=>onchoice?.({type:'reverse',card:kind})}><ArtCard {style} readableLandscape={!audit} title="A little medicine" reverse={!!fixture.reversed[kind]}><div class="wish-values"><span><b>1</b> Key 5 · Chapel 130</span><span><b>2</b> Medicine · Pharmacy 121</span><span><b>3</b> Return to your cell</span></div></ArtCard></button>
{:else if kind==='blessing'}<button class="object-button card-turn" aria-label={fixture.reversed[kind]?"Reveal blessing":"Turn blessing over"} onclick={()=>onchoice?.({type:'reverse',card:kind})}><ArtCard {style} readableLandscape={!audit} face="blessing" title="Extra Move" reverse={!!fixture.reversed[kind]}><p class="card-copy">Move <strong>1</strong> extra dot.</p><p class="card-copy secondary">Use once, then discard.</p></ArtCard></button>
{:else if kind==='patrol'}<button class="object-button card-turn" aria-label={fixture.reversed[kind]?"Reveal patrol card":"Turn patrol card over"} onclick={()=>onchoice?.({type:'reverse',card:kind})}><ArtCard {style} readableLandscape={!audit} face="movement" title="Garden Gate" reverse={!!fixture.reversed[kind]}>{#snippet artwork()}<PatrolMap/>{/snippet}<div class="patrol-values"><span><b>A</b> Pharmacy · 122</span><span><b>B</b> Garden Gate · 84</span><strong>16 steps · Blue patrol</strong></div></ArtCard></button>
{:else if kind==='backs'}<div class="back-study"><ArtCard {style} reverse/><b>Shared reverse art study</b></div>
{:else if kind==='tokens'}<div class="token-tray"><Token {style} label="Noise · ↑"/><Token {style} kind="vanished" label="Vanished · →"/></div>
{:else if kind==='die'}<DieReview {motion} review={audit}/>
{:else if kind==='key'}<div class="token-tray">{#each ['key','medicine'] as item}<button class="object-button token-choice" data-motion-id={item} data-motion-state={String(fixture[item as 'key'|'medicine'])} aria-pressed={fixture[item as 'key'|'medicine']} onclick={()=>onchoice?.({type:'collect',item:item as 'key'|'medicine'})}><Token {style} kind={item} label={item==='key'?'Chapel key':'Medicine'}/><span>{fixture[item as 'key'|'medicine']?'✓ Collected':'Tap to collect'}</span></button>{/each}</div>
{:else if kind==='status'}<section class="status-piece" data-motion-id="status" data-motion-state={String(fixture.caught)} aria-label="Novice status"><img class="aid-body" src={`${base}/art/${style}/parchment.webp`} alt=""/><Token {style} kind={fixture.caught?'noise':'vanished'} label=""/><h3>{fixture.caught?'Caught':'On the run'}</h3><p>{fixture.caught?'Walk toward your cell.':'Keep your secret.'}</p><span>{fixture.caught?'Keep your key. Return the medicine.':'A guard encounter can change your status.'}</span></section>
{:else if kind==='track'}<div class="painted-aid round-aid"><img class="aid-body" src={`${base}/art/${style}/parchment.webp`} alt=""/><h3>The night · round 6</h3><div class="round-track">{#each Array(15) as _,i}<span class:current={i===5}>{i+1}</span>{/each}</div><p>Captures <b>2 / 4</b> <span>4-player fixture</span></p></div>
{:else}<div class="painted-aid log-aid"><img class="aid-body" src={`${base}/art/${style}/parchment.webp`} alt=""/><h3>Celeste’s private log</h3><div class="log-row"><b>Round</b><b>Dot</b><b>Movement</b></div>{#each [['1a','30','Run · 5'],['1b','88','Run · 5'],['2','130','Walk · Key 5']] as row}<div class="log-row">{#each row as value}<span>{value}</span>{/each}</div>{/each}<p>Source graph · sample movement log</p></div>{/if}
</div>

<style>
 .card-turn{display:block;position:relative;padding:0;perspective:1100px}.player-components{width:100%;height:100%;min-height:0}.player-components .card-review-stack{height:100%;display:flex;align-items:center;justify-content:center}.player-components :global(.card-tray){display:grid;grid-template-columns:repeat(4,minmax(0,1fr));width:100%;max-width:1100px;gap:16px;overflow:visible;padding:10px 0}.player-components :global(.card-tray .painted-card){width:100%;min-width:0;max-width:285px}.player-components :global(.token-tray){justify-content:center}.player-components .status-piece{box-sizing:border-box;min-height:0;width:min(100%,300px);max-height:100%;padding:20px;flex-shrink:1}.player-components .status-piece :global(.painted-token){width:auto;min-width:0}.player-components .status-piece :global(.painted-token img){width:clamp(40px,12dvh,90px);height:clamp(40px,12dvh,90px)}.player-components .status-piece h3{margin:10px 0 8px}.player-components .status-piece>span{margin-top:10px}.player-components .card-turn{margin:auto;max-width:100%}
 @media(max-width:600px) and (min-height:500px){.player-components :global(.card-tray){grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;max-width:420px}}
 @media(max-height:500px){.player-components .status-piece{padding:12px;display:grid;grid-template-columns:64px minmax(0,1fr);column-gap:16px;text-align:left;max-width:440px;width:100%}.player-components .status-piece :global(.painted-token){grid-row:1 / 4}.player-components .status-piece h3{margin:0 0 6px}.player-components .status-piece>span{margin-top:6px}.player-components :global(.card-tray){max-width:720px;gap:10px}}
 @container(max-width:220px){.player-components :global(.movement-values>strong){font-size:22px}.player-components :global(.movement-values>span){font-size:12px}.player-components :global(.movement-values>b){font-size:16px;padding-top:5px;margin-top:2px}.player-components :global(.painted-title){font-size:18px}}
</style>
